/* From Uiverse.io by Cornerstone-04 - Tags: button */
.__UIV_SCOPE__ button {
  position: relative;
  background: none;
  border: solid 1px #121212;
  transition: linear 250ms;
  width: 100px;
  height: 40px;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 1rem;
}

.__UIV_SCOPE__ button:is(:hover,:focus) {
  color: #fff;
}

.__UIV_SCOPE__ button::after {
  position: absolute;
  content: '';
  inset: 0;
  z-index: -1;
  background-color: #121212;
  transform-origin: left;
  transform: scaleX(0);
  transition: linear 250ms;
}

.__UIV_SCOPE__ button:is(:hover, :focus)::after {
  transform: scale(1);
}
